<?php require_once __DIR__ . '/includes/db.php'; require_once __DIR__ . '/includes/functions.php'; $pdo=db(); $st=$pdo->prepare("SELECT * FROM galleries WHERE slug=? AND status='published'"); $st->execute([$_GET['slug']??'']); $g=$st->fetch(); if(!$g) die('Gallery not found.'); $st=$pdo->prepare('SELECT * FROM gallery_images WHERE gallery_id=? ORDER BY sort_order,id'); $st->execute([$g['id']]); $imgs=$st->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="assets/css/style.css"><title><?=h($g['title'])?></title></head><body><section class="section"><a href="index.php">← Home</a><h1><?=h($g['title'])?></h1><p><?=h($g['description'])?></p><div class="gallery-grid"><?php foreach($imgs as $im): ?><figure class="card"><div class="thumb"><img src="<?=h($im['file_path'])?>" alt="<?=h($im['alt_text'])?>"></div><figcaption><?=h($im['caption'])?></figcaption></figure><?php endforeach; ?></div></section></body></html>
